messages.content:
Tool response:
Tool: create_certification_scheme
Description: Creates a new certification scheme with specified name, recertification cycle, 
CEU requirements, and exam blueprint.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "recertification_cycle_years": {
          "type": "integer",
          "title": "Recertification Cycle Years"
        },
        "total_required_ceus": {
          "type": "integer",
          "title": "Total Required Ceus"
        },
        "min_categories": {
          "type": "integer",
          "title": "Min Categories"
        },
        "ceu_categories": {
          "items": {
            "properties": {
              "name": {
                "type": "string",
                "title": "Name"
              },
              "description": {
                "anyOf": [
                  {
                    "type": "string"
                  },
                  {
                    "type": "null"
                  }
                ],
                "title": "Description"
              }
            },
            "type": "object",
            "required": [
              "name"
            ],
            "title": "CEUCategoryItem"
          },
          "type": "array",
          "title": "Ceu Categories"
        },
        "exam_domains": {
          "items": {
            "properties": {
              "name": {
                "type": "string",
                "title": "Name"
              }
            },
            "type": "object",
            "required": [
              "name"
            ],
            "title": "ExamDomainItem"
          },
          "type": "array",
          "title": "Exam Domains"
        }
      },
      "required": [
        "name",
        "recertification_cycle_years",
        "total_required_ceus",
        "min_categories",
        "ceu_categories",
        "exam_domains"
      ]
    }
